using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Animation;
namespace OrbitLauncher;
public partial class MainWindow {
 static readonly CubicEase motionEase=new(){EasingMode=EasingMode.EaseOut};
 FrameworkElement? animatedPage;
 void UpdateLobbyIdle(){
  if(AvatarDragSurface==null)return;
  bool ambient=!brawlWebReady&&settings.Theme=="brawl stars"&&!settings.ReduceMotion&&WindowState!=WindowState.Minimized;LobbyBackground.SetMotion(ambient&&page=="Home");ThemeBackdrop.SetMotion(ambient&&page!="Home");
  var transform=AvatarDragSurface.RenderTransform as TranslateTransform??new TranslateTransform();AvatarDragSurface.RenderTransform=transform;
  transform.BeginAnimation(TranslateTransform.YProperty,null);transform.Y=0;
  if(brawlWebReady||settings.ReduceMotion||settings.Theme!="brawl stars"||page!="Home"||WindowState==WindowState.Minimized)return;
  transform.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(-2,2,TimeSpan.FromSeconds(2.4)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever,EasingFunction=new SineEase{EasingMode=EasingMode.EaseInOut}});
 }
 void ApplyMotionPreference(){UpdateLobbyIdle();Application.Current.Resources["ReduceMotion"]=settings.ReduceMotion;Application.Current.Resources["PopupMotion"]=settings.ReduceMotion?System.Windows.Controls.Primitives.PopupAnimation.None:System.Windows.Controls.Primitives.PopupAnimation.Fade;if(settings.ReduceMotion){((App)Application.Current).StopControlMotion(this);foreach(var panel in Visuals(this).OfType<Border>())if(panel.RenderTransform is TranslateTransform move){panel.BeginAnimation(OpacityProperty,null);panel.Opacity=1;move.BeginAnimation(TranslateTransform.YProperty,null);move.Y=0;}LobbySkinViewport?.StopEmote();if(animatedPage!=null){animatedPage.BeginAnimation(OpacityProperty,null);animatedPage.Opacity=1;if(animatedPage.RenderTransform is TranslateTransform t){t.BeginAnimation(TranslateTransform.YProperty,null);t.Y=0;}}if(HeroArtwork?.RenderTransform is TranslateTransform hero){hero.BeginAnimation(TranslateTransform.XProperty,null);hero.BeginAnimation(TranslateTransform.YProperty,null);hero.X=hero.Y=0;}}}
 void AnimatePage(string name){if(animatedPage!=null){animatedPage.BeginAnimation(OpacityProperty,null);animatedPage.Opacity=1;if(animatedPage.RenderTransform is TranslateTransform old){old.BeginAnimation(TranslateTransform.YProperty,null);old.Y=0;}}FrameworkElement target=name switch{"Library"=>LibraryPage,"Skins"=>SkinsPage,"Mods"=>ModsPage,"Worlds"=>FilesPage,"Settings"=>SettingsPage,"Logs"=>LogsPage,_=>settings.Theme=="brawl stars"?LobbyPage:HomePage};animatedPage=target;RevealPageContent(target);target.BeginAnimation(OpacityProperty,null);target.RenderTransform=new TranslateTransform();if(settings.ReduceMotion){target.Opacity=1;return;}target.BeginAnimation(OpacityProperty,new DoubleAnimation(.65,1,TimeSpan.FromMilliseconds(190)){EasingFunction=motionEase});((TranslateTransform)target.RenderTransform).BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(8,0,TimeSpan.FromMilliseconds(250)){EasingFunction=motionEase});App.FinishReveal(target,(TranslateTransform)target.RenderTransform,290);}
 void AnimateNavigation(Button button,bool active){button.ApplyTemplate();var old=(button.Background as SolidColorBrush)?.Color??Colors.Transparent;var color=active?(Color.FromRgb(22,58,53)):Colors.Transparent;var brush=new SolidColorBrush(color);button.Background=brush;button.Foreground=new SolidColorBrush(active?((SolidColorBrush)Application.Current.Resources["Brush00E5A0"]).Color:Color.FromRgb(167,189,205));var duration=TimeSpan.FromMilliseconds(settings.ReduceMotion?0:220);brush.BeginAnimation(SolidColorBrush.ColorProperty,new ColorAnimation(old,color,duration){EasingFunction=motionEase});if(button.Template.FindName("ActiveRail",button) is Border rail)rail.BeginAnimation(OpacityProperty,new DoubleAnimation(active?1:0,duration){EasingFunction=motionEase});}
 void HeroPointer_Move(object sender,MouseEventArgs e){if(settings.ReduceMotion||HeroArtwork.RenderTransform is not TranslateTransform t)return;var grid=(FrameworkElement)sender;var p=e.GetPosition(grid);double x=(p.X/Math.Max(1,grid.ActualWidth)-.5)*10,y=(p.Y/Math.Max(1,grid.ActualHeight)-.5)*7;t.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(x,TimeSpan.FromMilliseconds(220)){EasingFunction=motionEase});t.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(y,TimeSpan.FromMilliseconds(220)){EasingFunction=motionEase});}
 void HeroPointer_Leave(object sender,MouseEventArgs e){if(HeroArtwork.RenderTransform is not TranslateTransform t)return;var d=TimeSpan.FromMilliseconds(settings.ReduceMotion?0:300);t.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(0,d){EasingFunction=motionEase});t.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,d){EasingFunction=motionEase});}
}
